-- Icarus initial PostgreSQL schema. Apply through a reviewed migration pipeline.
CREATE TABLE users (id BIGSERIAL PRIMARY KEY, email TEXT UNIQUE NOT NULL, role TEXT NOT NULL, organization_id TEXT, password_hash TEXT, active BOOLEAN NOT NULL DEFAULT TRUE, oidc_subject TEXT UNIQUE);
CREATE TABLE sessions (token TEXT PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL, expires_at TIMESTAMPTZ NOT NULL);
CREATE INDEX sessions_expires_at_idx ON sessions(expires_at);
CREATE TABLE login_attempts (account_key TEXT PRIMARY KEY, attempts INTEGER NOT NULL CHECK (attempts >= 0), window_started_at DOUBLE PRECISION NOT NULL, updated_at DOUBLE PRECISION NOT NULL);
CREATE INDEX login_attempts_updated_at_idx ON login_attempts(updated_at);
CREATE TABLE applications (id BIGSERIAL PRIMARY KEY, reference TEXT UNIQUE NOT NULL, organization_id TEXT NOT NULL, organization_name TEXT NOT NULL, request_type TEXT NOT NULL, review_cycle TEXT NOT NULL, status TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, address TEXT DEFAULT '', scope_name TEXT DEFAULT '', requested_capacity INTEGER, updated_at TIMESTAMPTZ);
CREATE TABLE documents (id BIGSERIAL PRIMARY KEY, application_id BIGINT NOT NULL REFERENCES applications(id), document_type TEXT NOT NULL, original_name TEXT NOT NULL, storage_name TEXT NOT NULL, hash TEXT NOT NULL, confidence DOUBLE PRECISION, extraction_error TEXT, created_at TIMESTAMPTZ NOT NULL, malware_scan_status TEXT, malware_scan_detail TEXT, scanned_at TIMESTAMPTZ, supersedes_document_id BIGINT REFERENCES documents(id));
CREATE INDEX documents_application_id_idx ON documents(application_id);
CREATE TABLE extracted_fields (id BIGSERIAL PRIMARY KEY, document_id BIGINT NOT NULL REFERENCES documents(id), field_name TEXT NOT NULL, raw_value TEXT NOT NULL, normalized_value TEXT NOT NULL, page INTEGER NOT NULL, confidence DOUBLE PRECISION);
CREATE TABLE findings (id BIGSERIAL PRIMARY KEY, application_id BIGINT NOT NULL REFERENCES applications(id), document_id BIGINT REFERENCES documents(id), kind TEXT NOT NULL, severity TEXT NOT NULL, title TEXT NOT NULL, explanation TEXT NOT NULL, evidence TEXT, rule_id TEXT, rule_version TEXT, status TEXT NOT NULL, decision_reason TEXT, reviewed_by TEXT, evidence_page INTEGER);
CREATE INDEX findings_application_status_idx ON findings(application_id, status);
CREATE TABLE audit_events (id BIGSERIAL PRIMARY KEY, application_id BIGINT NOT NULL REFERENCES applications(id), actor TEXT NOT NULL, action TEXT NOT NULL, detail TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, previous_hash TEXT, event_hash TEXT);
CREATE TABLE verification_attempts (id BIGSERIAL PRIMARY KEY, application_id BIGINT NOT NULL REFERENCES applications(id), document_id BIGINT REFERENCES documents(id), method TEXT NOT NULL, status TEXT NOT NULL, mode TEXT NOT NULL, detail TEXT NOT NULL, checked_at TIMESTAMPTZ NOT NULL);
CREATE TABLE facility_reviews (id BIGSERIAL PRIMARY KEY, application_id BIGINT NOT NULL REFERENCES applications(id), document_id BIGINT NOT NULL REFERENCES documents(id), reviewer TEXT NOT NULL, outcome TEXT NOT NULL CHECK (outcome IN ('observed_no_issue','follow_up_required','inspection_recommended','unable_to_assess')), note TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE rule_settings (rule_id TEXT PRIMARY KEY, enabled BOOLEAN NOT NULL DEFAULT TRUE, updated_at TIMESTAMPTZ, updated_by TEXT);
CREATE TABLE rule_pack_versions (id BIGSERIAL PRIMARY KEY, version TEXT NOT NULL, snapshot_json TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('draft','published','superseded')), change_reason TEXT NOT NULL, created_by TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, approved_by TEXT, published_at TIMESTAMPTZ);
CREATE TABLE clarifications (id BIGSERIAL PRIMARY KEY, application_id BIGINT NOT NULL REFERENCES applications(id), message TEXT NOT NULL, requested_by TEXT NOT NULL, requested_at TIMESTAMPTZ NOT NULL, response TEXT, responded_by TEXT, responded_at TIMESTAMPTZ, status TEXT NOT NULL DEFAULT 'open');
